<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

function kimpu_register_button_controls( $customizer ) {
	$section = 'kimpu_design_buttons'; $customizer->add_section( $section, array( 'title' => __( 'Buttons & Forms', 'kimpu-multipurpose' ), 'panel' => 'kimpu_global_design', 'priority' => 50 ) );
	$customizer->add_setting( 'kimpu_design_button_style', array( 'default' => 'solid', 'sanitize_callback' => function( $v ) { return kimpu_sanitize_design_choice( $v, array( 'solid', 'outline', 'soft', 'ghost', 'text' ), 'solid' ); }, 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_design_button_style', array( 'label' => __( 'Default Button Style', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'select', 'choices' => array( 'solid' => __( 'Solid / Primary', 'kimpu-multipurpose' ), 'outline' => __( 'Outline', 'kimpu-multipurpose' ), 'soft' => __( 'Soft', 'kimpu-multipurpose' ), 'ghost' => __( 'Ghost', 'kimpu-multipurpose' ), 'text' => __( 'Text Link', 'kimpu-multipurpose' ) ) ) );
	$colors = array( 'button_primary_bg' => array( '#137c66', __( 'Primary Background', 'kimpu-multipurpose' ) ), 'button_primary_text' => array( '#ffffff', __( 'Primary Text', 'kimpu-multipurpose' ) ), 'button_primary_hover_bg' => array( '#0f6554', __( 'Primary Hover Background', 'kimpu-multipurpose' ) ), 'button_primary_hover_text' => array( '#ffffff', __( 'Primary Hover Text', 'kimpu-multipurpose' ) ), 'button_primary_border' => array( '#137c66', __( 'Primary Border', 'kimpu-multipurpose' ) ), 'button_secondary_bg' => array( '#17283b', __( 'Secondary Background', 'kimpu-multipurpose' ) ), 'button_secondary_text' => array( '#ffffff', __( 'Secondary Text', 'kimpu-multipurpose' ) ), 'button_secondary_hover_bg' => array( '#0f1720', __( 'Secondary Hover Background', 'kimpu-multipurpose' ) ), 'button_secondary_hover_text' => array( '#ffffff', __( 'Secondary Hover Text', 'kimpu-multipurpose' ) ), 'button_secondary_border' => array( '#17283b', __( 'Secondary Border', 'kimpu-multipurpose' ) ), 'button_outline_text' => array( '#137c66', __( 'Outline Text', 'kimpu-multipurpose' ) ), 'button_outline_hover_bg' => array( '#137c66', __( 'Outline Hover Background', 'kimpu-multipurpose' ) ), 'button_outline_hover_text' => array( '#ffffff', __( 'Outline Hover Text', 'kimpu-multipurpose' ) ), 'button_outline_border' => array( '#137c66', __( 'Outline Border', 'kimpu-multipurpose' ) ) );
	foreach ( $colors as $key => $data ) { kimpu_add_design_color( $customizer, 'kimpu_design_' . $key, $data[0], $data[1], $section ); }
	$fields = array( 'button_radius' => array( 10, 0, 40, __( 'Button Radius (px)', 'kimpu-multipurpose' ), 'kimpu_button_radius' ), 'button_pad_x' => array( 22, 8, 48, __( 'Horizontal Padding (px)', 'kimpu-multipurpose' ), '' ), 'button_pad_y' => array( 12, 6, 28, __( 'Vertical Padding (px)', 'kimpu-multipurpose' ), '' ), 'button_border_width' => array( 1, 0, 4, __( 'Border Width (px)', 'kimpu-multipurpose' ), '' ) );
	foreach ( $fields as $key => $data ) { $id = $data[4] ? $data[4] : 'kimpu_design_' . $key; $customizer->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $v ) use ( $data ) { return (int) kimpu_sanitize_design_number( $v, $data[1], $data[2] ); }, 'transport' => 'postMessage' ) ); $customizer->add_control( $id, array( 'label' => $data[3], 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => $data[1], 'max' => $data[2] ) ) ); }
	$form_fields = array( 'input_height' => array( 48, 36, 80, __( 'Input Height (px)', 'kimpu-multipurpose' ) ), 'input_radius' => array( 8, 0, 30, __( 'Input Radius (px)', 'kimpu-multipurpose' ) ), 'input_spacing' => array( 16, 4, 40, __( 'Field Spacing (px)', 'kimpu-multipurpose' ) ), 'label_spacing' => array( 6, 0, 20, __( 'Label Spacing (px)', 'kimpu-multipurpose' ) ) );
	foreach ( $form_fields as $key => $data ) { $id = 'kimpu_design_' . $key; $customizer->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $v ) use ( $data ) { return (int) kimpu_sanitize_design_number( $v, $data[1], $data[2] ); }, 'transport' => 'postMessage' ) ); $customizer->add_control( $id, array( 'label' => $data[3], 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => $data[1], 'max' => $data[2] ) ) ); }
	kimpu_add_design_color( $customizer, 'kimpu_design_placeholder_color', '#64748b', __( 'Placeholder Color', 'kimpu-multipurpose' ), $section );
}
